		case *ast.StructType:
			for _, field := range n.Fields.List {
				fieldNode := field.(*ast.Field)
				if !fieldNode.Type.Name.Equal("string") && !fieldNode.Type.Name.Equal("int") {
					continue // Only consider fields with type "struct" or "interface{}"
				}
				generateField(fieldNode, &n.Fields)
			}
		default:
			// Ignore other types if they don't correspond to our struct definition
		}
		return nil
	})

	// Convert generated fields into Avro schema definitions
	schemaMap := make(map[string]*avro.SchemaDefinition)
	for fieldName, fieldNode := range g.generatedFields {
		typeDef, ok := fieldNode.Type.(*ast.Ident)
		if !ok {
