		}
	}

	// Output the schema definitions as JSON
	jsonOutput, err := json.MarshalIndent(schemaMap, "", "\t")
	if err != nil {
		return fmt.Errorf("error marshalling schema map: %w", err)
	}

	// Write the JSON output to struct.avsc
	err = ioutil.WriteFile("struct.avsc", jsonOutput, 0644)
	if err != nil {
		return fmt.Errorf("error writing to file: %w", err)
	}

	return nil
